UPDATE LIVROS_NOMES N JOIN VW_LOTE_NOMES J ON J.NOME = N.NOME COLLATE utf8mb4_0900_ai_ci JOIN LIVROS_CATALOGO C ON C.TITULO = J.TITULO COLLATE utf8mb4_0900_ai_ci SET N.CATALOGO_ID = C.ID, N.ESTADO = 'OK', N.MOTIVO = LEFT(J.MOTIVO, 300) WHERE J.CHAVE = '{{chave}}' AND J.CONF = 'alta' AND N.ESTADO = 'PENDENTE'